/**
 * A3TAL-CHOOSER-PUBLISHED-VEHICLES-20261020
 * Display actual published vehicle records within the existing model chooser.
 * No new SEO landing pages or inferred model-specific technical claims.
 * Year/brand and destination always come from the same WordPress vehicle.
 */
add_filter('the_content', static function($html) {
  if (!is_page('choose-your-car') || !in_the_loop() || !is_main_query()) return $html;
  if (strpos($html, 'a3tal-chooser-available-vehicles') !== false) return $html;
  $cars = get_posts([
    'post_type' => 'a3_car',
    'post_status' => 'publish',
    'posts_per_page' => 12,
    'orderby' => 'modified',
    'order' => 'DESC',
    'ignore_sticky_posts' => true,
    'no_found_rows' => true,
    'suppress_filters' => false,
  ]);
  if (!$cars) return $html;
  $items = '';
  foreach ($cars as $car) {
    if (!($car instanceof WP_Post) || $car->post_status !== 'publish') continue;
    $url = get_permalink($car);
    if (!$url) continue;
    $name = get_the_title($car);
    if (!$name) continue;
    $brand = function_exists('a3g_first_term') ? a3g_first_term($car->ID, 'a3_brand') : '';
    $year = trim((string)get_post_meta($car->ID, '_a3_year', true));
    $image = has_post_thumbnail($car->ID)
      ? get_the_post_thumbnail($car->ID, 'medium', [
          'class' => 'a3tal-chooser-vehicle-image',
          'loading' => 'lazy',
          'decoding' => 'async',
          'alt' => '',
        ])
      : '<span class="a3tal-chooser-vehicle-fallback" aria-hidden="true">A3TAL</span>';
    $meta = [];
    if ($brand) $meta[] = esc_html($brand);
    if ($year && preg_match('/^20[0-9]{2}$/', $year)) $meta[] = esc_html($year);
    $items .= '<a class="a3tal-chooser-vehicle-card" href="'.esc_url($url).'">'
      .'<span class="a3tal-chooser-vehicle-media">'.$image.'</span>'
      .'<span class="a3tal-chooser-vehicle-info">'
      .($meta ? '<small>'.implode(' · ', $meta).'</small>' : '<small>صفحة سيارة منشورة</small>')
      .'<strong>'.esc_html($name).'</strong>'
      .'<em>عرض بيانات السيارة ←</em>'
      .'</span></a>';
  }
  if ($items === '') return $html;
  $archive = get_post_type_archive_link('a3_car') ?: home_url('/cars/');
  $section = '<section class="a3tal-chooser-available-vehicles" aria-labelledby="a3tal-chooser-vehicles-heading">'
    .'<div class="a3tal-chooser-catalog-head"><div>'
    .'<h2 id="a3tal-chooser-vehicles-heading">موديلات لها صفحات منشورة بالفعل</h2>'
    .'<p>ابدأ من بيانات السيارة المتاحة بروابط مباشرة، أو اختَر ماركة وموديلًا من القائمة التالية للبحث في المقالات. وجود صفحة سيارة لا يعني اكتمال كل شروحات أعطالها.</p>'
    .'</div><a class="a3tal-chooser-all-cars" href="'.esc_url($archive).'">عرض دليل السيارات بالكامل ←</a></div>'
    .'<div class="a3tal-chooser-vehicles-grid">'.$items.'</div>'
    .'</section>';
  $pattern='~(<h2\b[^>]*>\s*اختر الماركة ثم الموديل\s*</h2>)~iu';
  if (preg_match($pattern, $html)) {
    return preg_replace_callback($pattern, static function($match) use ($section) {
      return $section.$match[1];
    }, $html, 1);
  }
  return $section.$html;
}, 76);

/* A3TAL-CHOOSER-PUBLISHED-VEHICLES-20261020: index-friendly vehicle navigation, no new virtual pages. */
.a3tal-chooser-available-vehicles {
  margin: 16px 0 28px;
  padding: clamp(16px, 2.5vw, 26px);
  background: #f7fbff;
  border: 1px solid #dce6f2;
  border-radius: 18px;
  color: #163249;
}
.a3tal-chooser-catalog-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.a3tal-chooser-catalog-head > div { flex: 1 1 360px; min-width: 0; }
.a3tal-chooser-catalog-head h2 {
  font-size: clamp(21px, 2.5vw, 28px);
  line-height: 1.45;
  margin: 0 0 6px;
  color: #123b63;
}
.a3tal-chooser-catalog-head p {
  font-size: 14px;
  line-height: 1.8;
  color: #4b6077;
  margin: 0;
}
.a3tal-chooser-all-cars {
  display: inline-flex;
  align-items: center;
  align-self: center;
  border: 1px solid #d0e0ec;
  padding: 9px 12px;
  border-radius: 10px;
  color: #0c5379;
  background: white;
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}
.a3tal-chooser-vehicles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 205px), 1fr));
  gap: 12px;
}
.a3tal-chooser-vehicle-card {
  display: block;
  min-width: 0;
  overflow: hidden;
  border-radius: 14px;
  border: 1px solid #e1e9f0;
  background: white;
  color: #182f43;
  text-decoration: none;
  box-shadow: 0 3px 14px rgba(12, 40, 69, .045);
  transition: border-color .15s ease, transform .15s ease;
}
.a3tal-chooser-vehicle-card:hover,
.a3tal-chooser-vehicle-card:focus-visible {
  border-color: #4582a4;
  transform: translateY(-2px);
}
.a3tal-chooser-vehicle-media { display: block; height: 110px; overflow: hidden; background: #eff5f8; }
.a3tal-chooser-vehicle-image { display: block; width: 100%; height: 100%; object-fit: cover; }
.a3tal-chooser-vehicle-fallback {
  display: grid; place-items: center; height: 100%;
  color: #8aa4b9; font-size: 16px; font-weight: 800;
}
.a3tal-chooser-vehicle-info { display: grid; gap: 5px; padding: 12px; }
.a3tal-chooser-vehicle-info small { font-size: 11px; color: #547086; }
.a3tal-chooser-vehicle-info strong { font-size: 14px; line-height: 1.5; color: #123b63; }
.a3tal-chooser-vehicle-info em { font-size: 12px; font-style: normal; font-weight: 700; color: #17688b; }
@media (max-width: 620px) {
  .a3tal-chooser-vehicles-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; }
  .a3tal-chooser-vehicle-media { height: 82px; }
  .a3tal-chooser-vehicle-info { padding: 10px; }
  .a3tal-chooser-vehicle-info strong { font-size: 12.5px; }
  .a3tal-chooser-all-cars { width: 100%; justify-content: center; }
}
@media (prefers-reduced-motion: reduce) {
  .a3tal-chooser-vehicle-card { transition: none; }
  .a3tal-chooser-vehicle-card:hover { transform: none; }
}
